ee:message.ee:set-payload:
%dw 2.0
output application/json
var deletedCount = payload match {
	case n is Number -> n as Number
	case o is Object -> (o.deletedCount default o.n default 0) as Number
	else -> 0
}
---
if (deletedCount == 0)
{
  "status": 404,
  "code": "NOT_FOUND",
  "message": {
    "message": ""
  },
  "messageServer": "Data not found",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.exception.NotFoundExcecption"
    }
  ]
}
else
{
  "code": "200",
  "message": "Registro eliminado con exito",
  "deletedCount": deletedCount
}
